input.content:
workspace "Parcel Tracker" "A parcel delivery tracking platform" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "A customer who uses the platform to look up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company" {
            webPortal = container "Web Portal" "Where customers look up the status of their shipments" "Web application" {
                pricingRules = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Shared library"
            }
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers" "Service" {
                pricingRules = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Shared library"
            }
            database = container "Database" "Stores shipments and dispatch records" "Relational database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization" "External"

        customer -> parcelTracker.webPortal "looks up the status of their parcels" "HTTPS"
        parcelTracker.webPortal -> parcelTracker.database "reads shipment status from" "SQL"
        parcelTracker.dispatchService -> parcelTracker.database "reads and writes dispatch records to" "SQL"
        parcelTracker.dispatchService -> emailProvider "sends customer notification emails through" "SMTP"
    }

    views {
        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
            title "System Context for Parcel Tracker"
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
            title "Containers for Parcel Tracker"
        }

        component parcelTracker.webPortal "WebPortalComponents" {
            include *
            autoLayout
            title "Components of Web Portal"
        }

        component parcelTracker.dispatchService "DispatchServiceComponents" {
            include *
            autoLayout
            title "Components of Dispatch Service"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Component" {
                background #85BBF0
                color #000000
            }
            element "Database" {
                shape Cylinder
            }
        }
    }
}

