            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Component" {
                background #85BBF0
                color #000000
            }
            element "Database" {
                shape Cylinder
            }
        }
    }
}`;

const [validate, inspect, parse] = await Promise.allSettled([
  tools.structurizr.validate({ dsl }),
  tools.structurizr.inspect({ dsl }),
  tools.structurizr.parse({ dsl }),
]);

const fmt = (r) => r.status === "fulfilled" ? JSON.stringify(r.value, null, 2) : `REJECTED: ${r.reason}`;
return { validate: fmt(validate), inspect: fmt(inspect), parse: fmt(parse) };

